#include <set>
#include <string>

bool safeInDllMain(const std::string& action)
{
    static const std::set<std::string> safe{ "DisableThreadLibraryCalls", "InitializeCriticalSection", "TlsAlloc", "set a variable", "OutputDebugString" };
    return safe.count(action) > 0;
}
